import httpRequest from "@/apis/axios-api";
import type { CodeResult } from "@/types/request";
import type { AiProviderAdminItem } from "@/types/ai-provider";

// ===== AI 厂商管理后台（门禁 i-manage-ai，见 DidaOJ-go/web/controller/ai_provider.go）=====

// 全量列表（含停用项）
export function GetAiProviderAdminList(): Promise<CodeResult<AiProviderAdminItem[]>> {
  return httpRequest({
    url: "/manage/ai-provider/list",
    method: "get",
  });
}

// 新增厂商（key 是稳定标识，创建后不可改）
export function PostAiProviderAdd(params: {
  key: string;
  name: string;
  base_url: string;
  key_hint: string;
  docs_url: string;
  default_model: string;
}) {
  return httpRequest({
    url: "/manage/ai-provider/add",
    method: "post",
    data: params,
  });
}

// 更新厂商可变字段与启用状态（停用 = 下架）
export function PostAiProviderUpdate(params: {
  id: number;
  name: string;
  base_url: string;
  key_hint: string;
  docs_url: string;
  default_model: string;
  enabled: boolean;
}) {
  return httpRequest({
    url: "/manage/ai-provider/update",
    method: "post",
    data: params,
  });
}

// 物理删除厂商（引用该 key 的存量用户密钥将失效）
export function PostAiProviderDelete(id: number) {
  return httpRequest({
    url: "/manage/ai-provider/delete",
    method: "post",
    data: { id: id },
  });
}
