<script setup lang="ts">
// AI 厂商管理页：/manage/ai-provider（管理 tab 侧边栏，门禁 i-manage-ai）。
//
// 定位：维护用户侧 BYOK 的厂商白名单（数据库 ai_provider 表）。改动接入地址/停用厂商
// 会直接影响全体用户的 AI 功能，因此门禁独立于题目管理。改完立即生效（后端写后失效缓存）。
// key 是稳定标识：创建后不可改，改名只改 name；停用 = 下架（可恢复），删除 = 物理移除。

import { computed, onMounted, ref } from "vue";
import type { PrimaryTableCol, TableRowData } from "tdesign-vue-next";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo } from "@/util/tips";
import { useBreakpoint } from "@/composables/useBreakpoint";
import {
  GetAiProviderAdminList,
  PostAiProviderAdd,
  PostAiProviderUpdate,
  PostAiProviderDelete,
} from "@/apis/ai-provider";
import type { AiProviderAdminItem } from "@/types/ai-provider";

const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

const loading = ref(false);
const list = ref<AiProviderAdminItem[]>([]);

const columns: PrimaryTableCol<TableRowData>[] = [
  { colKey: "key", title: "标识（key）", width: 130 },
  { colKey: "name", title: "名称", width: 180 },
  { colKey: "base_url", title: "接口地址", width: 280, ellipsis: true },
  { colKey: "default_model", title: "默认模型", width: 170, ellipsis: true },
  { colKey: "enabled", title: "启用", width: 90 },
  { colKey: "modify_time", title: "更新时间", width: 170 },
  { colKey: "op", title: "操作", width: 120, fixed: "right" },
];

// 停用中的厂商数（提示运营关注）
const disabledCount = computed(() => list.value.filter((p) => !p.enabled).length);

// 切换启用状态的行 id（切换中显示 loading，防连点）
const togglingId = ref(0);

const load = async () => {
  loading.value = true;
  try {
    const res = await GetAiProviderAdminList();
    if (res.code === 0) {
      list.value = res.data ?? [];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "加载厂商列表失败");
  } finally {
    loading.value = false;
  }
};

// ── 启用/停用开关 ──

const onToggleEnabled = async (row: AiProviderAdminItem, enabled: boolean) => {
  togglingId.value = row.id;
  try {
    // 开关只改 enabled，其余字段原样带回（后端 update 是全量可变字段）
    const res = await PostAiProviderUpdate({
      id: row.id,
      name: row.name,
      base_url: row.base_url,
      key_hint: row.key_hint,
      docs_url: row.docs_url,
      default_model: row.default_model,
      enabled: enabled,
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      await load(); // 失败回滚展示状态
      return;
    }
    row.enabled = enabled;
    ShowTextTipsInfo(globalProperties, enabled ? `已启用 ${row.name}` : `已停用 ${row.name}（对用户即「下架」）`);
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "操作失败，请稍后重试");
    await load();
  } finally {
    togglingId.value = 0;
  }
};

// ── 新增 / 编辑弹窗 ──

const dialogVisible = ref(false);
// 编辑目标（null = 新增）
const editing = ref<AiProviderAdminItem | null>(null);
const saving = ref(false);

interface ProviderForm {
  key: string;
  name: string;
  base_url: string;
  key_hint: string;
  docs_url: string;
  default_model: string;
}

const emptyForm = (): ProviderForm => ({
  key: "",
  name: "",
  base_url: "",
  key_hint: "",
  docs_url: "",
  default_model: "",
});

const form = ref<ProviderForm>(emptyForm());
const isEditing = computed(() => editing.value != null);
const dialogTitle = computed(() => (isEditing.value ? "编辑厂商" : "新增厂商"));

const openAdd = () => {
  editing.value = null;
  form.value = emptyForm();
  dialogVisible.value = true;
};

const openEdit = (row: AiProviderAdminItem) => {
  editing.value = row;
  form.value = {
    key: row.key,
    name: row.name,
    base_url: row.base_url,
    key_hint: row.key_hint,
    docs_url: row.docs_url,
    default_model: row.default_model,
  };
  dialogVisible.value = true;
};

// 校验并提交。规则与后端 AiProviderService.Add/Update 对齐，前端先行提示
const validateForm = (): string => {
  if (!isEditing.value && !/^[a-z0-9-]{1,32}$/.test(form.value.key)) {
    return "标识（key）只能包含小写字母、数字与连字符，长度 1~32；创建后不可修改";
  }
  if (!form.value.name.trim()) {
    return "请填写厂商名称";
  }
  if (!form.value.base_url.trim().startsWith("https://")) {
    return "接口地址必须以 https:// 开头";
  }
  return "";
};

const onSubmit = async () => {
  const invalid = validateForm();
  if (invalid) {
    ShowTextTipsError(globalProperties, invalid);
    return;
  }
  saving.value = true;
  try {
    const res = isEditing.value
      ? await PostAiProviderUpdate({
          id: editing.value!.id,
          name: form.value.name,
          base_url: form.value.base_url,
          key_hint: form.value.key_hint,
          docs_url: form.value.docs_url,
          default_model: form.value.default_model,
          // 编辑不改变启用状态：保存的是「当前表单」，开关是表格上的独立操作
          enabled: editing.value!.enabled,
        })
      : await PostAiProviderAdd({
          key: form.value.key,
          name: form.value.name,
          base_url: form.value.base_url,
          key_hint: form.value.key_hint,
          docs_url: form.value.docs_url,
          default_model: form.value.default_model,
        });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, isEditing.value ? "已保存" : "已新增");
    dialogVisible.value = false;
    await load();
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "保存失败，请稍后重试");
  } finally {
    saving.value = false;
  }
};

// ── 删除确认 ──

const deleteDialogVisible = ref(false);
const deleteTarget = ref<AiProviderAdminItem | null>(null);
const deleting = ref(false);

const onAskDelete = (row: AiProviderAdminItem) => {
  deleteTarget.value = row;
  deleteDialogVisible.value = true;
};

const onConfirmDelete = async () => {
  const target = deleteTarget.value;
  if (!target) return;
  deleting.value = true;
  try {
    const res = await PostAiProviderDelete(target.id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsInfo(globalProperties, `已删除 ${target.name}`);
    deleteDialogVisible.value = false;
    await load();
  } catch (e) {
    console.error(e);
    ShowTextTipsError(globalProperties, "删除失败，请稍后重试");
  } finally {
    deleting.value = false;
  }
};

onMounted(() => {
  void load();
});
</script>

<template>
  <div class="manage-ai-provider">
    <t-alert theme="info" style="margin-bottom: 16px">
      <span>
        这里维护用户侧 AI 功能的<strong>厂商白名单</strong>（数据库配置，保存后立即生效）。
        「停用」等于下架：用户已存的该厂商密钥会被标记失效；「删除」为物理移除，同样使存量密钥失效。<strong>标识（key）创建后不可修改</strong>——改名请只改「名称」。
      </span>
    </t-alert>

    <div class="ai-provider-toolbar">
      <t-space :break-line="isMobile">
        <t-button theme="primary" @click="openAdd">新增厂商</t-button>
        <span v-if="disabledCount > 0" class="ai-provider-disabled-hint">
          当前有 {{ disabledCount }} 家处于停用状态
        </span>
      </t-space>
    </div>

    <t-loading :loading="loading">
      <t-table
        :data="list"
        :columns="columns"
        row-key="id"
        size="small"
        table-layout="auto"
        :scroll="{ x: 'max-content' }"
      >
        <template #enabled="{ row }">
          <t-switch
            :value="row.enabled"
            size="small"
            :loading="togglingId === row.id"
            @change="(val: boolean) => onToggleEnabled(row as AiProviderAdminItem, val)"
          />
        </template>
        <template #op="{ row }">
          <t-space size="small">
            <t-button size="small" variant="text" theme="primary" @click="openEdit(row as AiProviderAdminItem)"> 编辑 </t-button>
            <t-button size="small" variant="text" theme="danger" @click="onAskDelete(row as AiProviderAdminItem)">删除</t-button>
          </t-space>
        </template>
      </t-table>
    </t-loading>

    <t-dialog
      v-model:visible="dialogVisible"
      :header="dialogTitle"
      :width="isMobile ? '92%' : '560px'"
      :confirm-btn="{ content: '保存', loading: saving }"
      :cancel-btn="{ content: '取消' }"
      @confirm="onSubmit"
    >
      <t-form :colon="true" :data="form" label-align="top">
        <t-form-item label="标识（key）">
          <t-input
            v-model="form.key"
            :disabled="isEditing"
            placeholder="小写字母/数字/连字符，如 deepseek；创建后不可修改"
          />
          <div class="ai-provider-form-hint">
            与用户密钥落库值一一对应，是稳定标识：改名只改「名称」，删掉重建才算换 key（存量密钥将失效）。
          </div>
        </t-form-item>
        <t-form-item label="名称">
          <t-input v-model="form.name" placeholder="展示给用户的厂商名，如 DeepSeek" />
        </t-form-item>
        <t-form-item label="接口地址（OpenAI 兼容）">
          <t-input v-model="form.base_url" placeholder="https://api.example.com" />
        </t-form-item>
        <t-form-item label="密钥格式提示">
          <t-input v-model="form.key_hint" placeholder="如 sk-xxxx / id.secret，展示在用户填密钥的输入框里" />
        </t-form-item>
        <t-form-item label="申请文档地址">
          <t-input v-model="form.docs_url" placeholder="https://…（用户申请 API Key 的入口）" />
        </t-form-item>
        <t-form-item label="默认模型">
          <t-input v-model="form.default_model" placeholder="用户留空时使用；留空表示该厂商无默认值，用户必填" />
        </t-form-item>
      </t-form>
    </t-dialog>

    <t-dialog
      v-model:visible="deleteDialogVisible"
      header="删除厂商"
      :width="isMobile ? '92%' : '480px'"
      :confirm-btn="{ content: '删除', theme: 'danger', loading: deleting }"
      @confirm="onConfirmDelete"
    >
      <div>
        确定删除厂商「{{ deleteTarget?.name }}」（key：{{ deleteTarget?.key }}）吗？
      </div>
      <div class="ai-provider-delete-warn">
        删除后，用户已保存的该厂商密钥将全部失效（设置页标记「已失效」，AI 功能无法继续使用）。
        若只是暂时下架，建议改用「停用」开关，之后可随时恢复。
      </div>
    </t-dialog>
  </div>
</template>

<style scoped>
.manage-ai-provider {
  padding: 4px;
}

.ai-provider-toolbar {
  margin-bottom: 12px;
}

.ai-provider-disabled-hint {
  font-size: 13px;
  color: var(--td-warning-color, #e37318);
}

.ai-provider-form-hint {
  margin-top: 4px;
  font-size: 12px;
  line-height: 1.7;
  color: var(--td-text-color-placeholder, #999);
}

.ai-provider-delete-warn {
  margin-top: 8px;
  color: var(--td-warning-color, #e37318);
  font-size: 13px;
  line-height: 1.7;
}
</style>
